from openpyxl import load_workbook
import re
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
problems=[]
percentile_formulas=[]
for sh in wb.worksheets:
    for row in sh.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v, str) and v.startswith('='):
                tokens = re.findall(r'[A-Z][A-Z0-9.]*\s*(?=\()', v.upper())
                for t in tokens:
                    if t.startswith('PERCENTILE'):
                        percentile_formulas.append((sh.title, cell.coordinate, t, v))
                        if t != 'PERCENTILE.INC':
                            problems.append((sh.title, cell.coordinate, t, v))
print('Percentile formulas found:', len(percentile_formulas))
for item in percentile_formulas:
    print(item)
print('Bad percentile function tokens:', problems if problems else 'none')
print('PERCENTILE.INC all exact:', all(t == 'PERCENTILE.INC' for _,_,t,_ in percentile_formulas))
